322	                Map.of("commandKey", key("cu"), "volume", "0"), null, 400);
323	        postJson("/api/windows/" + windowId + "/curtailment",
324	                Map.of("commandKey", key("cu"), "volume", "-1"), null, 400);
325	        postJson("/api/windows/" + windowId + "/curtailment",
326	                Map.of("commandKey", key("cu"), "volume", "1.0001"), null, 400);
