336	    @Test
337	    void sameCommandKeySameParamsReplaysFirstResult() throws Exception {
338	        long windowId = createWindow("ch-idem-" + run,
339	                "2026-10-11T00:00:00Z", "2026-10-11T02:00:00Z", "5");
