359	    @Test
360	    void sameCommandKeyDifferentParamsReturns409() throws Exception {
361	        long windowId = createWindow("ch-idem2-" + run,
362	                "2026-10-12T00:00:00Z", "2026-10-12T02:00:00Z", "5");
363	        String commandKey = key("ac");
364	        postOk("/api/allocations", allocationBody(commandKey, key("ak"), windowId, "user-1", "1"), "alice");
365	        // 同键改水量 -> 409
366	        postJson("/api/allocations", allocationBody(commandKey, key("ak"), windowId, "user-1", "2"), "alice", 409);
367	        // 同键改操作人 -> 409
368	        postJson("/api/allocations", allocationBody(commandKey, key("ak"), windowId, "user-1", "1"), "bob", 409);
369	        // 窗口创建同键改参 -> 409
370	        String windowCommand = key("wc");
371	        String windowKey = key("wk");
372	        postOk("/api/windows", windowBody(windowCommand, windowKey, "ch-x-" + run,
