395	        JsonNode history = getOk("/api/windows/" + windowId + "/history");
396	        assertEquals(windowId, history.get("window").get("id").asLong());
397	        assertEquals("10", history.get("window").get("availableTotal").asText());
398	        assertEquals(2, history.get("allocations").size());
399	        assertEquals("APPROVED", history.get("allocations").get(0).get("status").asText());
400	        assertEquals("CANCELLED", history.get("allocations").get(1).get("status").asText());
